package com.boss.businessmodel.domain; import com.boss.common.domain.TenantScopedEntity; import jakarta.persistence.*;
@Entity @Table(name="business_models") public class BusinessModel extends TenantScopedEntity { @Column(nullable=false,length=100) private String code; @Column(nullable=false,length=200) private String name; @Column(length=2000) private String configurationJson; protected BusinessModel(){} public BusinessModel(String c,String n,String j){code=c;name=n;configurationJson=j;} public String getCode(){return code;} public String getName(){return name;} public String getConfigurationJson(){return configurationJson;} public void setConfigurationJson(String j){configurationJson=j;} }
